FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Based on:
// https://en.wikipedia.org/wiki/Tetrakis_hexahedron
// https://en.wikipedia.org/wiki/Truncated_octahedron
// Dual polyhedron: Tetrakis Hexahedron
float hgsdfTetrakisHexahedronHard(vec3 p, float r)
{
    float b = 2.0;

    vec3 v0   = normalize(vec3( 0, 1, b));
    vec3 v1   = normalize(vec3( 0,-1, b));
    vec3 v2   = normalize(vec3( 0, b, 1));
    vec3 v3   = normalize(vec3( 0,-b, 1));
    vec3 v4   = normalize(vec3( 1, 0, b));
    vec3 v5   = normalize(vec3(-1, 0, b));
    vec3 v6   = normalize(vec3( 1, b, 0));
    vec3 v7   = normalize(vec3(-1, b, 0));
    vec3 v8   = normalize(vec3( b, 0, 1));
    vec3 v9   = normalize(vec3(-b, 0, 1));
    vec3 v10  = normalize(vec3( b, 1, 0));
    vec3 v11  = normalize(vec3(-b, 1, 0));

    float d = 0.0;
    d = max(d, abs(dot(p, v0 )) );
    d = max(d, abs(dot(p, v1 )) );
    d = max(d, abs(dot(p, v2 )) );
    d = max(d, abs(dot(p, v3 )) );
    d = max(d, abs(dot(p, v4 )) );
    d = max(d, abs(dot(p, v5 )) );
    d = max(d, abs(dot(p, v6 )) );
    d = max(d, abs(dot(p, v7 )) );
    d = max(d, abs(dot(p, v8 )) );
    d = max(d, abs(dot(p, v9 )) );
    d = max(d, abs(dot(p, v10)) );
    d = max(d, abs(dot(p, v11)) );

    return d - r;
}
